2. /** Name of the index to use */
3. indexName: string;
4. /** Type of index scan */
5. type: 'equality' | 'range';
6. /** For equality lookups: the key fields and their values */
7. equalityFields?: Record<string, unknown>;
8. /** For range queries: the field and bounds */
9. rangeField?: string;
10. rangeBounds?: RangeBounds;
11. /** Filter conditions not covered by the index (need post-filtering) */
12. remainingFilter: Filter<Document> | null;

